const AMB = "#d9822b", RED = "#c62828", MUT = "#5d7880", TEAL = "#2a9d8f";
let E = {};
function seg(api, t, a, b) { return api.seg(t, a, b, "ease_in_out"); }
function moveArt(api, id, parent) { const a = api.$(id); parent.appendChild(a); return a; }
function tag(api, g, txt, x, y, color) { return R.text(api, g, txt, x, y, {anchor: "middle", size: 16, weight: 800, color, halo: false}); }
function tile(api, g) {
  api.el("rect", {x: 46, y: 182, width: 164, height: 200, rx: 20, fill: "#fff6ea", stroke: AMB, "stroke-width": 3, "stroke-dasharray": "9 7"}, g);
}

function conn(api, g, sx, sy, zx, zy, zr, col) {
  const dx = zx - sx, dy = zy - sy, d = Math.hypot(dx, dy), a = Math.atan2(dy, dx), b = Math.acos(zr / d);
  const tp = (s) => [zx - zr * Math.cos(a + s * b), zy - zr * Math.sin(a + s * b)], p1 = tp(1), p2 = tp(-1);
  return api.el("path", {d: `M${sx} ${sy}L${p1[0].toFixed(1)} ${p1[1].toFixed(1)}M${sx} ${sy}L${p2[0].toFixed(1)} ${p2[1].toFixed(1)}`, stroke: col || "#5d7880", "stroke-width": 2, "stroke-dasharray": "5 5", opacity: 0.6, fill: "none"}, g);
}
function blob(api, rnd, cx, cy, r, n) { n = n || 9; const pts = [];
  for (let i = 0; i < n; i++) { const a = i / n * Math.PI * 2, rr = r * (0.72 + 0.5 * rnd()); pts.push([cx + rr * Math.cos(a), cy + rr * Math.sin(a) * 0.8]); }
  let d = ""; for (let i = 0; i < n; i++) { const p0 = pts[(i + n - 1) % n], p1 = pts[i], p2 = pts[(i + 1) % n], m0 = [(p0[0] + p1[0]) / 2, (p0[1] + p1[1]) / 2], m1 = [(p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2];
    d += (i ? "" : `M${m0[0].toFixed(1)} ${m0[1].toFixed(1)}`) + `Q${p1[0].toFixed(1)} ${p1[1].toFixed(1)} ${m1[0].toFixed(1)} ${m1[1].toFixed(1)}`; }
  return d + "Z"; }
function drawOn(api, p, f) { const L = p._L || (p._L = p.getTotalLength()); p.setAttribute("stroke-dasharray", `${(L * f).toFixed(1)} ${(L + 20).toFixed(1)}`); p.setAttribute("opacity", f > 0 ? 1 : 0); }
function drops(api, g, pts, color) { return pts.map(([x, y, d]) => { const e = api.el("path", {d: "M0 -7C4 -2 5 2 0 5C-5 2 -4 -2 0 -7Z", fill: color || "#c62828", stroke: "#fff", "stroke-width": 1, opacity: 0}, g); e._p = [x, y, d]; return e; }); }
function dropsUpdate(api, ds, t, on, fall) { ds.forEach((e) => { const [x, y, d] = e._p, f = (((t + d) % 1500) / 1500); api.set(e, {transform: `translate(${x} ${(y + f * (fall || 40)).toFixed(1)})`, opacity: (on * Math.sin(f * Math.PI)).toFixed(3)}); }); }

const ZX = 484, ZY = 300, ZR = 110;
function setup(api) {
  const rnd = api.random(5), A = api.svg;
  api.el("defs", {}, A).innerHTML = '<clipPath id="zc"><circle cx="484" cy="300" r="110"/></clipPath><radialGradient id="lin" cx=".4" cy=".35" r=".9"><stop offset="0" stop-color="#fbd9cf"/><stop offset=".7" stop-color="#f1ab9f"/><stop offset="1" stop-color="#d98479"/></radialGradient>';
  // rectum tube continuing the sigmoid
  const rg = api.el("g", {}, A);
  api.el("path", {d: "M 290 352 C 318 338 340 352 336 392 L 334 462", fill: "none", stroke: "#b5616b", "stroke-width": 36, "stroke-linecap": "round"}, rg);
  api.el("path", {d: "M 290 352 C 318 338 340 352 336 392 L 334 462", fill: "none", stroke: "#eba49d", "stroke-width": 30, "stroke-linecap": "round"}, rg);
  api.el("ellipse", {cx: 334, cy: 466, rx: 14, ry: 6, fill: "#7a2d33"}, rg);
  // continuous inflammation overlay: rectum -> sigmoid -> colon
  const ov = api.el("g", {"stroke-linecap": "round", "stroke-linejoin": "round", fill: "none"}, A);
  const dd = ["M 334 464 L 334 392 C 338 352 316 340 290 352 C 275 378 250 392 222 400 C 195 400 175 386 152 378", "M 150 376 C 124 366 102 356 101 330 L 101 250", "M 101 250 C 92 226 70 205 74 184 C 84 162 126 154 160 166 C 180 172 192 186 204 204"];
  const wd = [34, 66, 40];
  E.ov = dd.map((d, i) => api.el("path", {d, stroke: "#d32f2f", "stroke-width": wd[i], opacity: 0, "stroke-opacity": 0.5, style: "mix-blend-mode:multiply"}, ov));
  // lens
  conn(api, api.$("#conn") || A, 128, 312, ZX, ZY, ZR);
  api.el("circle", {cx: 128, cy: 312, r: 8, fill: "none", stroke: "#5d7880", "stroke-width": 2.5}, A);
  api.el("circle", {cx: ZX, cy: ZY, r: ZR, fill: "url(#lin)"}, A);
  const zg = api.el("g", {"clip-path": "url(#zc)"}, A);
  // folds of the lining
  [[-70, -60, 150, 0.3], [-90, -5, 160, 0.3], [-75, 55, 150, 0.3]].forEach(([dx, dy, w, s]) => api.el("path", {d: `M${ZX + dx} ${ZY + dy}Q${ZX + dx + w / 2} ${ZY + dy - 34} ${ZX + dx + w} ${ZY + dy + 4}`, fill: "none", stroke: "#fff", "stroke-opacity": 0.55, "stroke-width": 7, "stroke-linecap": "round"}, zg));
  E.red = api.el("rect", {x: ZX - ZR, y: ZY - ZR, width: ZR * 2, height: ZR * 2, fill: "#d32f2f", opacity: 0}, zg);
  E.ul = [[-52, -38, 30, 20], [34, -52, 24, 17], [-12, 8, 34, 22], [54, 30, 26, 18], [-60, 52, 22, 15]].map(([dx, dy, rx, ry]) => {
    const g = api.el("g", {opacity: 0}, zg), x = ZX + dx, y = ZY + dy;
    api.el("path", {d: blob(api, rnd, x, y, rx, 9), fill: "#7a1218", stroke: "#e57373", "stroke-width": 3.5}, g);
    api.el("ellipse", {cx: x - rx * 0.2, cy: y - ry * 0.25, rx: rx * 0.35, ry: ry * 0.22, fill: "#fff", opacity: 0.35}, g);
    return g; });
  E.dr = drops(api, zg, [[ZX - 52, ZY - 20, 0], [ZX - 12, ZY + 30, 400], [ZX + 54, ZY + 50, 800], [ZX + 34, ZY - 30, 1100], [ZX - 60, ZY + 70, 600]], "#b71c1c");
  api.el("circle", {cx: ZX, cy: ZY, r: ZR, fill: "none", stroke: "#5d7880", "stroke-width": 4}, A);
  // bleeding at the rectum (beat 1)
  E.bd = drops(api, A, [[326, 462, 0], [336, 462, 500], [344, 462, 1000]], "#c62828");
  E.glow = R.glow(api, A, 334, 440, {r: 26, color: "#e53935"});
  // labels
  const L = api.el("g", {}, A);
  E.cCol = [R.leader(api, L, 212, 160, 168, 164, MUT), R.chip(api, L, "Colon", 218, 164, MUT, {size: 18})];
  E.cRec = [R.leader(api, L, 348, 440, 336, 428, MUT), R.chip(api, L, "Rectum", 352, 446, MUT, {size: 18})];
  E.cBld = R.chip(api, L, "Bloody diarrhoea", 352, 496, AMB, {size: 18});
  E.cUl = [R.leader(api, L, 556, 190, ZX + 36, ZY - 46, RED), R.chip(api, L, "Ulcers", 520, 178, RED, {size: 18})];
  E.cAns = R.chip(api, L, "Ulcerative colitis", 352, 496, RED, {size: 22});
  E.cInf = [R.leader(api, L, 168, 262, 124, 280, RED), R.chip(api, L, "Continuous\ninflammation", 170, 246, RED, {size: 17})];
}
function render(t, api) {
  R.fade(api, E.cCol, t, 250, 700); R.fade(api, E.cRec, t, 450, 900);
  dropsUpdate(api, E.bd, t, seg(api, t, 300, 800) * (1 - seg(api, t, 2300, 2800)), 34);
  E.glow.update(t, 0.8 * seg(api, t, 300, 800) * (1 - seg(api, t, 2400, 3000)));
  R.fade(api, E.cBld, t, 600, 1000, 2250, 2550);
  // beat 2: inflammation spreads upward without a gap
  drawOn(api, E.ov[0], api.seg(t, 2400, 3300, "ease_in_out")); drawOn(api, E.ov[1], api.seg(t, 3200, 4000, "ease_in_out")); drawOn(api, E.ov[2], api.seg(t, 3900, 4600, "ease_in_out"));
  api.set(E.red, {opacity: (0.32 * seg(api, t, 2500, 3600)).toFixed(3)});
  E.ul.forEach((g, i) => { const k = api.ease("back_out", api.seg(t, 3000 + i * 260, 3500 + i * 260, "linear")); api.set(g, {opacity: k > 0 ? 1 : 0, transform: `translate(${ZX} ${ZY}) scale(${Math.max(0.001, k).toFixed(3)}) translate(${-ZX} ${-ZY})`}); });
  dropsUpdate(api, E.dr, t, seg(api, t, 3700, 4200), 38);
  R.fade(api, E.cUl, t, 3900, 4300, 4650, 4950);
  // beat 3
  R.fade(api, E.cInf, t, 4700, 5200);
  R.fade(api, E.cAns, t, 4900, 5400);
}
